          "python -m pip install -e .",
          "or use virtualenv with make install && source venv/bin/activate"
        ],
        "OpenAI_API_key_configuration": "export OPENAI_API_KEY=[your key] or use .env file from .env.template"
      },
      "CONTRIBUTING.md": {
        "dependencies_installation": [
          "pip install -e .",
          "pip install -e .[doc]"
        ],
        "pre_commit_hooks": [
          "pre-commit install",
          "make dev-install"
        ],
        "formatting_and_linting": "Pre-commit hooks run black and ruff on commit"
      },
      "CI_and_test_execution": {
        "python_version": "3.10",
        "install_package": "pip install -e .",
        "test_dependencies": "pip install pytest pytest-cov",
        "run_tests_with_coverage": "pytest --cov=gpt_engineer"
